function openCampaign(kind,b=null){
  if($('happy-hour-sheet'))return;
  const deadline=b?bannerDeadline(b):null;
  const linkedStore=b?.link_type==='store'?b.link_value:null;
  const offers=kind==='happy'?hhStores(true):ALLS.filter(s=>s.c==='rest'&&
    (kind==='discount'?s.disc>0:hasFreeDelivery(s))).map(s=>({
      s,open:TLB.isOpen(s.n),p:kind==='discount'?s.disc:0,end:deadline
    })).sort((a,c)=>Number(c.open)-Number(a.open)||c.p-a.p);
  const rows=linkedStore&&kind!=='happy'?offers.filter(o=>o.s.id===linkedStore):offers;
  const lead=rows[0],end=b?deadline:(kind==='happy'?lead?.end:null);
  if(!lead&&!b)return;
  const title=t(kind==='happy'?'hHhT':kind==='discount'?'bestOffers':'hFreeT');
  const menus=TLB.allMenus(true),sheet=document.createElement('dialog');
  sheet.id='happy-hour-sheet';
  sheet.className='hh-sheet';
  sheet.setAttribute('aria-labelledby','hh-sheet-title');
  sheet.innerHTML=`<header class="hh-sheet-hero">
    <form method="dialog"><button class="hh-sheet-close" aria-label="${esc(t('roCancel'))}">${ico('x',18)}</button></form>
    <span class="hh-sheet-clock" aria-hidden="true">${ico('clock',40)}</span>
    <h2 id="hh-sheet-title">${title}</h2>
    ${lead?.p?`<strong class="hh-sheet-ribbon">${t('happyLead').replace('{pct}',lead.p)}</strong>`:''}
    ${end?managedHappyCountdown(end)+`<p>${t('happyHurry')}</p>`:''}
  </header><div class="hh-sheet-list">${rows.length?rows.map(offer=>happyHourRow(offer,menus)).join(''):`<p>${t('noStores')}</p>`}</div>`;
  sheet.addEventListener('close',()=>sheet.remove(),{once:true});
  sheet.addEventListener('click',event=>{if(event.target===sheet)sheet.close()});
  document.body.append(sheet);
  sheet.showModal();
}

