/* Home categories use the available column width on compact phones. */
#app .d6h .d6-cats {
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 2px;
  padding: 12px 6px 10px;
}
#app .d6h .d6-ct { min-width: 0; gap: 6px; }
#app .d6h .d6-ct span {
  width: min(100%, 56px);
  height: auto;
  aspect-ratio: 1;
}
#app .d6h .d6-ct img { width: min(80%, 44px); height: auto; }
#app .d6h .d6-ct b {
  font-size: clamp(10px, 2.7vw, 11px);
  font-weight: 600;
  overflow: visible;
  text-overflow: clip;
}

#app .d6h .home-heading { align-items: center; gap: 5px; padding: 15px 12px 7px; }
#app .d6h .home-heading h2 { gap: 5px; font-size: 18px; line-height: 22px; font-weight: 900; white-space: nowrap; }
#app .d6h .home-heading h2 :is(b, span) { font-weight: inherit; font-size: inherit; line-height: inherit; }
.home-heading h2 img { flex: none; width: 26px; height: 26px; object-fit: contain; }
.home-heading h2 span { overflow: visible; }
.home-heading i { font-style: normal; display: grid; place-items: center; flex: none; }
[data-section="again"] i { background: var(--o); color: white; border-radius: 50%; width: 34px; height: 34px; transform: rotate(-18deg); }
[data-section="again"] b { box-shadow: inset 0 -6px #d9f99d; }
[data-section="offers"] h2 b { color: white; background: var(--o); padding: 3px 9px 3px 17px; clip-path: polygon(9px 0,100% 0,100% 100%,9px 100%,0 50%); position: relative; }
[data-section="offers"] h2 b::before { content: ""; position: absolute; left: 7px; top: 44%; background: white; border-radius: 50%; width: 4px; height: 4px; }
#app .d6h [data-section="popular"] h2 { display: grid; justify-items: start; gap: 1px; }
[data-section="popular"] small { color: var(--o); text-transform: uppercase; font-size: 10px; letter-spacing: 2px; }
[data-section="popular"] h2 span { display: flex; align-items: center; gap: 4px; }
[data-section="popular"] em { color: var(--o); letter-spacing: -2px; }
[data-section="picks"] b { background: #3b1d14; color: white; border-radius: 4px; padding: 3px 7px; transform: rotate(-2deg); }
[data-section="picks"] b:last-child { background: #d9f99d; color: #3b1d14; transform: rotate(2deg); }
[data-section="rewards"] b { padding: 4px 12px; color: white; background: #1e2433; mask: radial-gradient(circle 5px at 0 50%,transparent 98%,#000) left/51% 100% no-repeat,radial-gradient(circle 5px at 100% 50%,transparent 98%,#000) right/51% 100% no-repeat; }
[data-section="dine"] h2 b { color: var(--o); }
[data-section="dine"] i { border: 2px dashed var(--o); color: var(--o); width: 34px; height: 34px; border-radius: 50%; transform: rotate(-12deg); font-size: 13px; }
@media(max-width:374px){
  #app .d6h .home-heading { padding-inline: 8px; gap: 2px; }
  #app .d6h .home-heading h2 { gap: 3px; }
  .home-heading h2 img { width: 21px; height: 21px; }
}

#app .d6h .home-again .d6-lo { width: 84px; padding: 0; position: relative; border: 0; border-radius: 0; font: inherit; color: inherit; background: transparent; cursor: pointer; align-self: start; }
#app .d6h .home-again .d6-ph { width: 84px; height: 84px; border: 1px solid var(--line); border-radius: 16px; background: white; }
#app .d6h .home-again .dish-store-logo { position: relative; inset: auto; width: 100%; height: 100%; border: 0; border-radius: inherit; font-size: 34px; line-height: 1; }
#app .d6h .home-again .nm { font-size: 12px; line-height: 16px; margin: 6px 0 0; white-space: normal; overflow-wrap: anywhere; text-align: center; color: var(--mut2); }
.home-deal { position: absolute; top: 66px; left: 50%; transform: translateX(-50%); padding: 2px 7px; border-radius: 6px; background: #d9f99d; color: #26371b; font-size: 11px; font-weight: 700; line-height: 15px; white-space: nowrap; }
.home-again .closed { filter: grayscale(1); cursor: default; }

.home-picks-summary { margin: 0 16px 8px; color: var(--mut2); font-size: 13px; line-height: 20px; }
.home-picks-summary b { color: var(--ink); font-size: 17px; font-weight: 700; }
.home-picks { background: #f7f3ee; padding-bottom: 12px; }
#app .d6h .home-picks .d6-pt, #app .d6h .home-picks .d6-ph { width: 150px; }
#app .d6h .home-picks .d6-ph { height: 150px; border-radius: 16px; border: 1px solid var(--line); background: white; }
#app .d6h .home-picks .nm { min-height: 0; line-height: 18px; font-weight: 600; }
#app .d6h .home-picks .st { margin-top: 4px; white-space: normal; }
.home-picks .d6-pa { left: 2px; right: auto; color: var(--o); }
#app .d6h .home-picks .px { display: inline; box-shadow: inset 0 -4px #d9f99d; }
.home-picks .px s { background: #f7f3ee; padding-inline-start: 4px; margin: 0; }

#app .d6h .d6-dn { margin: 0 16px; width: auto; }
#app .d6h .home-dine { padding-inline: 16px; scroll-padding-inline: 16px; }
#app .d6h .home-dine .d6-dc, #app .d6h .home-dine .d6-ph { width: 250px; }
#app .d6h .home-dine .d6-ph { height: 130px; border-radius: 16px; }
#app .d6h .home-dine .hb { top: 8px; right: 8px; left: auto; color: #26371b; background: #d9f99d; }
#app .d6h .home-dine .hrt { top: 2px; right: auto; left: 2px; }
#app .d6h .home-dine .nm span { white-space: normal; }

/* An undecodable primary photo has the same state as a missing catalogue photo. */
.home-again .d6-lo:has(.d6-ph.none),
.home-picks:not(.home-meals) .d6-pt:has(.d6-ph.none),
.home-heading[data-section="again"]:not(:has(+ .home-again .d6-ph:not(.none))),
.home-again:not(:has(.d6-ph:not(.none))),
.home-picks:not(.home-meals):not(:has(.d6-ph:not(.none))) { display: none; }
#app .d6h :is(.d6-nc,.d6-sc,.d6-dc) > .d6-ph.none { display: none; }
#app .d6h .d6-sc.closed, #app .d6h .d6-nc.closed { filter: grayscale(1); }

.cart-choice { width: min(360px,calc(100% - 32px)); margin: auto; padding: 20px; color: var(--ink); border: 0; border-radius: 18px; }
.cart-choice::backdrop { background: rgb(0 0 0 / 48%); }
.cart-choice h2 { font-size: 20px; margin: 0 0 8px; }
.cart-choice p { margin: 0 0 20px; overflow-wrap: anywhere; }
.cart-choice form > div { display: flex; gap: 10px; }
.cart-choice .btn { flex: 1; }
.cart-choice .btn.s { border: 1px solid var(--line); background: white; }

#app .d6h [data-section="popular"] + .d6-rl {
  display: grid;
  grid-auto-flow: column;
  grid-template-rows: repeat(2, max-content);
  grid-auto-columns: 150px;
  align-items: start;
}
#app .d6h :is([data-section="popular"] + .d6-rl, .d6-nr):not(:has(> :nth-child(4))) {
  grid-template-rows: auto;
}
#app .d6h [data-section="popular"] + .d6-rl .d6-sc,
#app .d6h [data-section="popular"] + .d6-rl .d6-sc > .d6-ph { width: 150px; }
#app .d6h [data-section="popular"] + .d6-rl .d6-sc > .d6-ph { height: 150px; }

#app .d6h .d6-sc .pk { display: inline-block; max-width: 100%; white-space: nowrap; text-overflow: ellipsis; overflow: hidden; vertical-align: top; box-sizing: border-box; }
#app .d6h .d6-sc > .mt, #app .d6h .d6-sc > .pk { margin-inline: 0; }
.dish-store-logo { position: absolute; top: 8px; right: 8px; display: grid; place-items: center; width: 36px; height: 36px; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: white; color: var(--ink); font-weight: 700; }
.dish-store-logo > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; background: white; }

[data-section="meals"] h2 b { background: var(--o); color: white; padding: 2px 6px; border-radius: 6px; }
[data-section="meals"] h2 b:nth-of-type(2) { background: #3b1d14; }
.home-expanded .d6-rl { flex-wrap: wrap; justify-content: center; }
[data-section="advert"] h2 b { border: 2px solid #3b1d14; padding: 2px 10px; border-radius: 999px; transform: rotate(-3deg); }
.home-ad-card { margin: 0 16px; width: calc(100% - 32px); display: flex; align-items: stretch; min-height: 142px; text-align: start; background: #f7f3ee; border: 0; border-radius: 18px; overflow: hidden; color: #3b1d14; padding: 0; font: inherit; }
.home-ad-card .ad-copy { flex: 1; display: grid; align-content: center; gap: 6px; padding: 14px; }
