.flash-description .px { white-space: nowrap; font-size: 14px; letter-spacing: -.02em; }
.flash-description .px s { white-space: nowrap; font-size: 11px; margin-left: 3px; }

/* BRIEF-25c Y-02 — all DineOut cards keep a corner brand mark; missing covers have a branded fill. */
#app .d6h .home-dine .dine-brand-cover { position: relative; display: grid; place-items: center; isolation: isolate; background: var(--dine-mark-bg,#813c2d); }
#app .d6h .home-dine .dine-brand-cover > img.dine-fallback-mark { position:absolute; inset:12%; width:76%; height:76%; object-fit:contain; z-index:1; border-radius:12px; }
